// Reference solution
function ethernetFrame(payload) {
  var padded = Math.max(payload, 46), frame = 14 + padded + 4, wire = frame + 20;
  return { padded: padded, frameBytes: frame, wireBytes: wire, efficiency: Math.round(payload / wire * 10000) / 100 };
}

